import { styled as gooberStyled } from 'goober'

// Vite's SSR transform (used by Vitest) rewrites imported calls like
// `styled(...)` into property-access calls on the module namespace object
// (`mod.styled(...)`), binding `this` to that (non-extensible) namespace
// object. goober's internals assume an unbound `this`, so calling it that
// way throws "Cannot add property p, object is not extensible" the first
// time a styled component actually renders. The `(0, fn)(...)` idiom forces
// an unbound call regardless of how the reference was obtained.
export const styled: typeof gooberStyled = (...args) => (0, gooberStyled)(...(args as Parameters<typeof gooberStyled>))

