1	import { useState, useEffect } from 'react'
2	import { Box, Button, Loader, Stack, Text, Tooltip } from '@mantine/core'
3	import DetailPanel from '../DetailPanel'
4	import Toolbar from '../Toolbar'
5	import DriveFolderPickerModal from './DriveFolderPickerModal'
6	import DriveThumbnailPanel from './ThumbnailPanel'
7	import GroupNode from './GroupNode'
8	import FileList from './FileList'
9	import ResizableLeftPanel from './ResizableLeftPanel'
10	import UploadModal from './UploadModal'
11	import { useFileTree, flattenFiles, LocalFile } from './useFileTree'
12	import { useDriveAssignments, resolveEffectiveAssignments, DriveAssignment, PickerTarget } from './useDriveAssignments'
13	import * as uploadQueue from './uploadQueue'
14	import * as pageCache from '../../lib/pageCache'
15	import { ellipsisPath } from '../../utils'
16	
17	export default function DriveUploadMode() {
18	  const { root, tree, loading, error, pickRoot } = useFileTree()
19	  const isEmpty = tree !== null && tree.files.length === 0 && tree.subgroups.length === 0
20	
21	  const [selectedFile, setSelectedFile] = useState<LocalFile | null>(null)
22	  const [selectedPage, setSelectedPage] = useState(1)
23	  const handleSelectFile = (file: LocalFile) => {
24	    setSelectedFile(file)
25	    setSelectedPage(1)
26	  }
27	
28	  useEffect(() => {
29	    return () => { if (selectedFile) pageCache.evict(selectedFile.path) }
30	    // eslint-disable-next-line react-hooks/exhaustive-deps
31	  }, [selectedFile?.path])
32	
33	  // Groups start expanded; presence in this set (keyed by the group's full
34	  // path, e.g. "invoices/2026") means collapsed.
35	  const [collapsedGroups, setCollapsedGroups] = useState<Set<string>>(new Set())
36	  const toggleGroup = (groupKey: string) => {
37	    setCollapsedGroups(prev => {
38	      const next = new Set(prev)
39	      if (next.has(groupKey)) next.delete(groupKey); else next.add(groupKey)
40	      return next
41	    })
42	  }
43	
44	  const assignments = useDriveAssignments()
45	  const [pickerTarget, setPickerTarget] = useState<PickerTarget | null>(null)
46	  const handlePicked = (folder: DriveAssignment) => {
47	    if (pickerTarget?.type === 'group') assignments.setGroupAssignment(pickerTarget.key, folder)
48	    else if (pickerTarget?.type === 'file') assignments.setFileOverride(pickerTarget.path, folder)
49	    setPickerTarget(null)
50	  }
51	
52	  const [uploadModalOpen, setUploadModalOpen] = useState(false)
53	  const allFiles = tree ? flattenFiles(tree) : []
54	  const effectiveAssignments = tree ? resolveEffectiveAssignments(tree, assignments) : null
55	  const readyToUpload = allFiles.length > 0 && allFiles.every(f => effectiveAssignments!.get(f.path) != null)
56	  const handleUploadAll = () => {
57	    if (!tree || !effectiveAssignments) return
58	    uploadQueue.start(allFiles.map(f => {
59	      const assignment = effectiveAssignments.get(f.path)
60	      // Upload All is disabled until readyToUpload is true, so every file
61	      // should resolve here — this is a defensive check against that
62	      // guard and this walk drifting out of sync, not an expected path.
63	      if (!assignment) throw new Error(`No Drive folder assigned for "${f.path}"`)
64	      return { path: f.path, folderId: assignment.driveFolderId, name: f.name }
65	    }))
66	    setUploadModalOpen(true)
67	  }
68	
69	  return (
70	    <Box style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
71	      <Toolbar>
72	        <Button size="xs" variant="default" onClick={pickRoot}>
73	          {root ? ellipsisPath(root) : 'Choose root folder…'}
74	        </Button>
75	        <Box style={{ flex: 1 }} />
76	        <Tooltip
77	          label={tree ? 'Every file needs a Drive folder before uploading' : 'Choose a root folder first'}
78	          disabled={readyToUpload}
79	        >
80	          <span>
81	            <Button size="xs" disabled={!readyToUpload} onClick={handleUploadAll}>
82	              Upload All
83	            </Button>
84	          </span>
85	        </Tooltip>
86	      </Toolbar>
87	
88	      <Box style={{ flex: 1, overflow: 'hidden', display: 'flex' }}>
89	        <ResizableLeftPanel
90	          left={
91	            <>
92	              <DriveFolderPickerModal
93	                opened={pickerTarget !== null}
94	                onClose={() => setPickerTarget(null)}
95	                onSelect={handlePicked}
96	              />
97	              {tree && (
98	                <UploadModal
99	                  opened={uploadModalOpen}
100	                  tree={tree}
101	                  onClose={() => setUploadModalOpen(false)}
102	                />
103	              )}
104	
105	              {loading && <Loader size="sm" />}
106	              {error && <Text size="sm" c="red">{error}</Text>}
107	              {!loading && !error && isEmpty && (
108	                <Text size="sm" c="dimmed">No files found under this folder.</Text>
109	              )}
110	
111	              {tree && (
112	                <Stack gap="md">
113	                  {tree.subgroups.map(group => (
114	                    <GroupNode
115	                      key={group.name}
116	                      group={group}
117	                      groupKey={group.name}
118	                      collapsedGroups={collapsedGroups}
119	                      onToggle={toggleGroup}
120	                      assignments={assignments}
121	                      inheritedAssignment={null}
122	                      onPick={setPickerTarget}
123	                      selectedPath={selectedFile?.path ?? null}
124	                      onSelectFile={handleSelectFile}
125	                    />
126	                  ))}
127	                  <FileList
128	                    files={tree.files}
129	                    assignments={assignments}
130	                    inheritedAssignment={null}
131	                    onPick={setPickerTarget}
132	                    selectedPath={selectedFile?.path ?? null}
133	                    onSelectFile={handleSelectFile}
134	                  />
135	                </Stack>
136	              )}
137	            </>
138	          }
139	        >
140	          <DriveThumbnailPanel
141	            pdfPath={selectedFile?.path ?? null}
142	            pageCount={selectedFile?.pageCount ?? 0}
143	            selectedPage={selectedPage}
144	            onSelectPage={setSelectedPage}
145	          />
146	
147	          {selectedFile
148	            ? <DetailPanel pdfPath={selectedFile.path} pageNum={selectedPage} pageCount={selectedFile.pageCount} />
149	            : <Box style={{ flex: 1, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }} />}
150	        </ResizableLeftPanel>
151	      </Box>
152	    </Box>
153	  )
154	}
